# DeepSeek 审查请求（开发期真实任务）

任务：审查 EnArrower 的规则引擎与求解器代码，聚焦边界用例与状态一致性，提出可执行的改进建议或确认现有实现正确。

请重点检查以下方面，并逐条给出结论（正确 / 存在风险 / 建议修改），如建议修改请给出最小改动思路：

1. 共线箭头平移的路径校验：`checkMove` 只检查头部前沿到边缘的射线，是否遗漏了多格箭身（len 2/3）在移动中扫过的格子？自身原占用格是否会被误判为阻挡？
2. 机关切换时机：`applyMove` 是否严格先按移动前门状态校验、成功离场后才切换？开关箭头能否依靠自己离场打开的门穿过原本关闭的门？
3. 同组多开关：两个同组开关先后离场是否会正确切换两次（奇偶性）？是否影响其他组？
4. 通关判定：最后一支开关箭头离场后即使关门，`isWin` 是否仍返回 true？
5. 求解器：记忆化 DFS 的 `stateKey` 是否足以区分所有规则状态（剩余箭头集合 + 各组门状态）？`dead` 集合的剪枝是否会错误地把可解状态判为无解？
6. 提示：`hint` 是否保证推荐的箭头执行后仍存在完整解法？当前无解但仍有局部可移动箭头时是否返回 dead-end？
7. 撤销快照：`GameSession.commitMove` 是否在提交前保存完整快照（箭头 + 门状态），被阻挡时是否不写历史？

输出格式：按编号列出结论与理由；最后给出 3 条最值得补充的单元测试边界用例。不要重写整个文件，只指出问题与最小修改。

以下是被审查的真实代码：

### 文件：src/core/rules.ts
```ts
import {
  ArrowDef,
  Cell,
  DIR_VEC,
  GameState,
  GroupId,
  LevelDef,
  MoveCheck,
  MoveResult,
} from './types';

export function cellsOf(arrow: ArrowDef): Cell[] {
  const v = DIR_VEC[arrow.dir];
  const cells: Cell[] = [];
  for (let i = 0; i < arrow.len; i++) {
    cells.push({ x: arrow.head.x - v.x * i, y: arrow.head.y - v.y * i });
  }
  return cells;
}

export function cellKey(c: Cell): string {
  return `${c.x},${c.y}`;
}

export function inBoard(level: LevelDef, c: Cell): boolean {
  return c.x >= 0 && c.y >= 0 && c.x < level.width && c.y < level.height;
}

export function arrowById(level: LevelDef, id: string): ArrowDef {
  const a = level.arrows.find((x) => x.id === id);
  if (!a) throw new Error(`arrow ${id} not in level ${level.id}`);
  return a;
}

export function initialState(level: LevelDef): GameState {
  const open: Partial<Record<GroupId, boolean>> = {};
  for (const m of level.mechanisms) open[m.group] = m.initialOpen;
  return {
    levelId: level.id,
    remaining: level.arrows.map((a) => a.id),
    open,
  };
}

export function cloneState(state: GameState): GameState {
  return {
    levelId: state.levelId,
    remaining: [...state.remaining],
    open: { ...state.open },
  };
}

export function gateMap(level: LevelDef): Map<string, GroupId> {
  const map = new Map<string, GroupId>();
  for (const m of level.mechanisms) {
    for (const g of m.gates) map.set(cellKey(g), m.group);
  }
  return map;
}

/**
 * 箭头共线平移，只需检查头部前沿到棋盘边缘的射线。
 * 自身原占用格天然不在射线上；开启闸门可通过，关闭闸门与其他箭头阻挡。
 */
export function checkMove(level: LevelDef, state: GameState, arrowId: string): MoveCheck {
  const arrow = arrowById(level, arrowId);
  const v = DIR_VEC[arrow.dir];
  const occupied = new Map<string, string>();
  for (const id of state.remaining) {
    if (id === arrowId) continue;
    for (const c of cellsOf(arrowById(level, id))) occupied.set(cellKey(c), id);
  }
  const gates = gateMap(level);
  let c: Cell = { x: arrow.head.x + v.x, y: arrow.head.y + v.y };
  while (inBoard(level, c)) {
    const key = cellKey(c);
    const blockerArrow = occupied.get(key);
    if (blockerArrow) {
      return { ok: false, blocker: { kind: 'arrow', arrowId: blockerArrow, cell: { ...c } } };
    }
    const group = gates.get(key);
    if (group && !state.open[group]) {
      return { ok: false, blocker: { kind: 'gate', group, cell: { ...c } } };
    }
    c = { x: c.x + v.x, y: c.y + v.y };
  }
  return { ok: true };
}

/** 先按移动前门状态校验；成功离场后才切换机关，一次性返回新状态。 */
export function applyMove(level: LevelDef, state: GameState, arrowId: string): MoveResult {
  const check = checkMove(level, state, arrowId);
  if (!check.ok) {
    return { ok: false, blocker: check.blocker, state };
  }
  const next = cloneState(state);
  next.remaining = next.remaining.filter((id) => id !== arrowId);
  const arrow = arrowById(level, arrowId);
  let toggledGroup: GroupId | undefined;
  if (arrow.group) {
    next.open[arrow.group] = !next.open[arrow.group];
    toggledGroup = arrow.group;
  }
  return { ok: true, state: next, toggledGroup };
}

export function isWin(state: GameState): boolean {
  return state.remaining.length === 0;
}

export function legalMoves(level: LevelDef, state: GameState): string[] {
  return state.remaining.filter((id) => checkMove(level, state, id).ok);
}

/** 尾部完全出界所需的平移格数，供动画使用（规则无关，仅几何）。 */
export function exitDistance(level: LevelDef, arrow: ArrowDef): number {
  const v = DIR_VEC[arrow.dir];
  const tail = {
    x: arrow.head.x - v.x * (arrow.len - 1),
    y: arrow.head.y - v.y * (arrow.len - 1),
  };
  if (arrow.dir === 'right') return level.width - tail.x;
  if (arrow.dir === 'left') return tail.x + 1;
  if (arrow.dir === 'down') return level.height - tail.y;
  return tail.y + 1;
}

export function stateKey(state: GameState): string {
  const groups = Object.keys(state.open).sort() as GroupId[];
  const flags = groups.map((g) => (state.open[g] ? '1' : '0')).join('');
  return `${[...state.remaining].sort().join('.')}|${flags}`;
}
```

### 文件：src/core/solver.ts
```ts
import { applyMove, isWin, legalMoves, stateKey } from './rules';
import { GameState, LevelDef } from './types';

export interface SolveResult {
  solvable: boolean;
  /** 一条完整解法（箭头 id 序列）；无解时为 null。 */
  solution: string[] | null;
  /** 搜索过的不同状态数，用于记录求解规模。 */
  visited: number;
}

/**
 * 记忆化深度优先搜索。第一版上限 12 支箭头、2 组机关，
 * 状态空间 <= 2^12 * 4，无需更复杂的求解系统。
 */
export function solve(level: LevelDef, start: GameState): SolveResult {
  const dead = new Set<string>();
  const visited = new Set<string>();
  const path: string[] = [];

  function dfs(state: GameState): boolean {
    if (isWin(state)) return true;
    const key = stateKey(state);
    visited.add(key);
    if (dead.has(key)) return false;
    for (const id of legalMoves(level, state)) {
      const result = applyMove(level, state, id);
      path.push(id);
      if (dfs(result.state)) return true;
      path.pop();
    }
    dead.add(key);
    return false;
  }

  const solvable = dfs(start);
  return { solvable, solution: solvable ? [...path] : null, visited: visited.size };
}

export type HintResult =
  | { kind: 'move'; arrowId: string }
  | { kind: 'dead-end' }
  | { kind: 'won' };

/** 提示必须保证“执行后仍可通关”，不能把局部可移动当作正确下一步。 */
export function hint(level: LevelDef, state: GameState): HintResult {
  if (isWin(state)) return { kind: 'won' };
  const current = solve(level, state);
  if (!current.solvable || !current.solution) return { kind: 'dead-end' };
  return { kind: 'move', arrowId: current.solution[0] };
}
```

### 文件：src/core/session.ts
```ts
import { applyMove, checkMove, cloneState, initialState, isWin } from './rules';
import { GameState, LevelDef, MoveResult } from './types';

/**
 * 一局游戏的规则会话：状态 + 撤销历史。纯数据，无 DOM。
 * 动画由界面层负责；这里只在动作确认成功时提交。
 */
export class GameSession {
  readonly level: LevelDef;
  state: GameState;
  history: GameState[] = [];

  constructor(level: LevelDef, state?: GameState, history?: GameState[]) {
    this.level = level;
    this.state = state ? cloneState(state) : initialState(level);
    if (history) this.history = history.map(cloneState);
  }

  get canUndo(): boolean {
    return this.history.length > 0;
  }

  get won(): boolean {
    return isWin(this.state);
  }

  /** 提交一次成功移动：先存快照，再一次性移除箭头并切换机关。 */
  commitMove(arrowId: string): MoveResult {
    const snapshot = cloneState(this.state);
    const result = applyMove(this.level, this.state, arrowId);
    if (result.ok) {
      this.history.push(snapshot);
      this.state = result.state;
    }
    return result;
  }

  check(arrowId: string) {
    return checkMove(this.level, this.state, arrowId);
  }

  undo(): boolean {
    const prev = this.history.pop();
    if (!prev) return false;
    this.state = prev;
    return true;
  }

  restart(): void {
    this.state = initialState(this.level);
    this.history = [];
  }
}
